{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_store_category_price_matrix AS WITH active_scorecard_stores AS ( SELECT DISTINCT branch_code FROM snitch_db.maplemonk.fresh_mix_score ), category_catalog_percentiles AS ( SELECT UPPER(TRIM(category)) AS category, ROUND(PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY COALESCE(CURRENT_SLASHED_PRICE, PRICE))) AS p25, ROUND(PERCENTILE_CONT(0.60) WITHIN GROUP (ORDER BY COALESCE(CURRENT_SLASHED_PRICE, PRICE))) AS p60, ROUND(PERCENTILE_CONT(0.85) WITHIN GROUP (ORDER BY COALESCE(CURRENT_SLASHED_PRICE, PRICE))) AS p85 FROM snitch_db.maplemonk.availability_master_v2 WHERE COALESCE(CURRENT_SLASHED_PRICE, PRICE) > 0 AND category IS NOT NULL GROUP BY UPPER(TRIM(category)) ), normalized_store_fact AS ( SELECT f.branch_code::VARCHAR AS branch_code, f.selling_price, f.suborder_quantity, CASE WHEN UPPER(TRIM(f.category)) IN (\'DENIM\', \'DENIMS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(f.category)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\', \'CASUAL TROUSER\', \'CASUAL TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(f.category)) IN (\'CARGO\', \'CARGO PANTS\') THEN \'CARGO PANTS\' ELSE UPPER(TRIM(f.category)) END AS category FROM snitch_db.maplemonk.store_fact_items_offline f WHERE f.suborder_quantity > 0 AND f.selling_price > 0 AND f.category IS NOT NULL ), store_category_historical_asp AS ( SELECT nf.branch_code, nf.category, SUM(nf.selling_price) / NULLIF(SUM(nf.suborder_quantity), 0) AS store_category_asp FROM normalized_store_fact nf INNER JOIN active_scorecard_stores a ON nf.branch_code = a.branch_code::VARCHAR GROUP BY nf.branch_code, nf.category ), store_sweet_spots AS ( SELECT s.branch_code, COALESCE(mf.\"STORE NAME\", \'BRANCH_\' || s.branch_code) AS store_name, s.category, CASE WHEN s.store_category_asp IS NULL THEN \'Mid-Range (₹\' || c.p25 || \' - ₹\' || c.p60 || \')\' WHEN s.store_category_asp < c.p25 THEN \'Budget (< ₹\' || c.p25 || \')\' WHEN s.store_category_asp BETWEEN c.p25 AND c.p60 THEN \'Mid-Range (₹\' || c.p25 || \' - ₹\' || c.p60 || \')\' WHEN s.store_category_asp BETWEEN c.p60 AND c.p85 THEN \'Premium (₹\' || c.p60 || \' - ₹\' || c.p85 || \')\' ELSE \'Super Premium (> ₹\' || c.p85 || \')\' END AS sweet_price_bucket FROM store_category_historical_asp s LEFT JOIN category_catalog_percentiles c ON s.category = c.category LEFT JOIN snitch_db.maplemonk.master_file mf ON s.branch_code = mf.\"STORE CODE\"::VARCHAR ) SELECT branch_code, store_name, SHIRTS, TSHIRTS, JEANS, TROUSERS, CARGO_PANTS, JACKETS, HOODIES, SWEATSHIRTS, SHORTS, BLAZERS, SWEATERS, OVERSHIRT FROM store_sweet_spots PIVOT ( MAX(sweet_price_bucket) FOR category IN ( \'SHIRTS\', \'T-SHIRTS\', \'JEANS\', \'TROUSERS\', \'CARGO PANTS\', \'JACKETS\', \'HOODIES\', \'SWEATSHIRTS\', \'SHORTS\', \'BLAZERS\', \'SWEATERS\', \'OVERSHIRT\' ) ) AS p ( BRANCH_CODE, STORE_NAME, SHIRTS, TSHIRTS, JEANS, TROUSERS, CARGO_PANTS, JACKETS, HOODIES, SWEATSHIRTS, SHORTS, BLAZERS, SWEATERS, OVERSHIRT ) ORDER BY BRANCH_CODE;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            